    test("human - mpileup - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] =  [ [ id:'test', single_end:false, sex:'XX' ], // meta map
                            [],
                            [],
                            [],[],[],[]
                        ]
                // fasta
                input[1] = []
                // fai
                input[2] = []
                // snp_position
                input[3] = []
                // known_snps
                input[4] = []
                // known_snps_tbi
                input[5] = []
                // chr_directory
                input[6] = file("${projectDir}/chr_dir")
                // mappability
                input[7] = []
                // target_bed
                input[8] = []
                // gccontent_profile
                input[9] = []
                """
                }
        }

        then {
